export const TIME_RATIO=3;
export const ISLAND_SITES=new Set(['G6','G7','B3','B4','C6','C7','C8','C9','C10']);
const finite=(n,min=0,max=Infinity)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;
export function distanceMetres(a,b){const r=x=>x*Math.PI/180;const v=Math.sin(r(b[0]-a[0])/2)**2+Math.cos(r(a[0]))*Math.cos(r(b[0]))*Math.sin(r(b[1]-a[1])/2)**2;return 6371000*2*Math.atan2(Math.sqrt(v),Math.sqrt(Math.max(0,1-v)))}
