export function normaliseRoadResponse(data,mode='car'){if(data?.code!=='Ok'||!data.routes?.[0]||data.waypoints?.length!==2)throw Error('No route');const r=data.routes[0],seconds=r.legs?.flatMap(l=>l.annotation?.duration||[])||[];if(r.geometry?.type!=='LineString')throw Error('Invalid geometry');return validateRoute({path:r.geometry.coordinates.map(p=>[p[1],p[0]]),segmentSeconds:seconds,mode,sourceSeconds:r.duration,durationSeconds:modeDuration(mode,r.distance,r.duration),distanceMetres:r.distance,startAccessMetres:data.waypoints[0].distance,endAccessMetres:data.waypoints[1].distance});}
export function validateJourney(j,sites,now=Date.now()){if(!j||j.version!==1||!Number.isSafeInteger(j.startedAt)||!sites.some(s=>s.id===j.fromId)||!sites.some(s=>s.id===j.toId)||!finite(j.startedAt,1,now+60000)||!finite(j.pausedMs,0,now-j.startedAt+60000)||(j.pausedAt!==null&&!finite(j.pausedAt,j.startedAt,now+60000)))throw Error('Invalid journey');const from=sites.find(s=>s.id===j.fromId),to=sites.find(s=>s.id===j.toId);if(ISLAND_SITES.has(from.id)||ISLAND_SITES.has(to.id))throw Error('Unsupported sea route');const route=validateRoute(j.route);if(distanceMetres(route.path[0],[from.lat,from.lng])>1500||distanceMetres(route.path.at(-1),[to.lat,to.lng])>1500)throw Error('Wrong route endpoints');return {version:1,fromId:j.fromId,toId:j.toId,route,startedAt:j.startedAt,pausedMs:j.pausedMs,pausedAt:j.pausedAt};}
export function journeyAt(j,now=Date.now()){const gameMs=Math.ceil(j.route.durationSeconds/TIME_RATIO*1000),elapsedMs=Math.max(0,(j.pausedAt??now)-j.startedAt-j.pausedMs),fraction=Math.min(1,elapsedMs/gameMs),waitMs=j.route.mode==='bus'?120000/TIME_RATIO:0,movingFraction=Math.max(0,Math.min(1,(elapsedMs-waitMs)/Math.max(1,gameMs-waitMs))),sum=j.route.segmentSeconds.reduce((a,b)=>a+b,0),target=movingFraction*sum;if(elapsedMs<waitMs)return {fraction,position:[...j.route.path[0]],index:0,waiting:true,remainingMs:Math.max(0,gameMs-elapsedMs),gameMs,arrived:false};let spent=0,index=0;while(index<j.route.segmentSeconds.length-1&&spent+j.route.segmentSeconds[index]<=target){spent+=j.route.segmentSeconds[index];index++}const duration=j.route.segmentSeconds[index],part=duration>0?Math.min(1,Math.max(0,(target-spent)/duration)):1,a=j.route.path[index],b=j.route.path[index+1];const position=fraction>=1?[...j.route.path.at(-1)]:[a[0]+(b[0]-a[0])*part,a[1]+(b[1]-a[1])*part];return {fraction,position,index,waiting:elapsedMs<waitMs,remainingMs:Math.max(0,gameMs-elapsedMs),gameMs,arrived:fraction>=1};}
export function formatClock(ms){const s=Math.max(0,Math.ceil(ms/1000)),h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=s%60;return h?`${h}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}`;}
